"""
CGN 提取层 - 静态 AST 提取引擎

融合：
- Graphify: Tree-sitter 统一接口
- code-review-graph: 22语言广覆盖，保守精确提取
- GitNexus: 语言感知导入解析（TS路径别名/Rust模块/Go包/装饰器检测）
"""

from __future__ import annotations
import ast
import json
import re
import sys
from pathlib import Path
from typing import Any

from .models import (
    ConfidenceLevel, Edge, ExtractionMethod, ExtractionResult, Node
)

# ─────────────────────────── 基础提取器接口 ───────────────────────────

class BaseExtractor:
    """所有语言提取器的基类"""

    language: str = ""

    def extract(self, path: Path) -> ExtractionResult:
        raise NotImplementedError

    def _make_node_id(self, path: Path, name: str, kind: str) -> str:
        """生成全局唯一节点 ID"""
        return f"{path}::{kind}::{name}".replace(" ", "_")

    def _make_edge(
        self, src: str, dst: str, relation: str,
        confidence: ConfidenceLevel = ConfidenceLevel.EXTRACTED,
        score: float = 1.0,
    ) -> Edge:
        return Edge(
            source=src, target=dst, relation=relation,
            confidence=confidence, confidence_score=score,
            extraction_method=ExtractionMethod.AST_STATIC,
        )


# ─────────────────────────── Python 提取器 ───────────────────────────

class PythonExtractor(BaseExtractor):
    """Python AST 提取器（使用内置 ast 模块，无 tree-sitter 依赖）"""

    language = "python"

    def extract(self, path: Path) -> ExtractionResult:
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
            tree = ast.parse(source, filename=str(path))
        except SyntaxError as e:
            return ExtractionResult([], [], str(path), ExtractionMethod.AST_STATIC, "python",
                                    error=f"SyntaxError: {e}")

        nodes: list[Node] = []
        edges: list[Edge] = []
        module_id = self._make_node_id(path, path.stem, "module")

        # 模块节点
        nodes.append(Node(
            id=module_id, label=path.stem, kind="module",
            source_file=str(path), source_location="L1",
            extraction_method=ExtractionMethod.AST_STATIC, language="python"
        ))

        visitor = PythonASTVisitor(path, module_id, self)
        visitor.visit(tree)
        nodes.extend(visitor.nodes)
        edges.extend(visitor.edges)

        return ExtractionResult(nodes, edges, str(path), ExtractionMethod.AST_STATIC, "python")


class PythonASTVisitor(ast.NodeVisitor):
    """Python AST 访问器，提取函数/类/导入/调用"""

    def __init__(self, path: Path, module_id: str, extractor: PythonExtractor):
        self.path = path
        self.module_id = module_id
        self.extractor = extractor
        self.nodes: list[Node] = []
        self.edges: list[Edge] = []
        self._scope_stack: list[str] = [module_id]

    @property
    def _current_scope(self) -> str:
        return self._scope_stack[-1]

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            target_id = f"external::{alias.name}"
            self.edges.append(self.extractor._make_edge(
                self._current_scope, target_id, "imports"
            ))
        self.generic_visit(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        module = node.module or ""
        target_id = f"external::{module}"
        self.edges.append(self.extractor._make_edge(
            self._current_scope, target_id, "imports"
        ))
        self.generic_visit(node)

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        fn_id = self.extractor._make_node_id(self.path, node.name, "function")
        decorators = [ast.unparse(d) for d in node.decorator_list]
        sig = f"def {node.name}({', '.join(ast.unparse(a) for a in node.args.args)})"
        docstring = ast.get_docstring(node) or ""

        self.nodes.append(Node(
            id=fn_id, label=node.name, kind="function",
            source_file=str(self.path),
            source_location=f"L{node.lineno}-L{node.end_lineno}",
            signature=sig, docstring=docstring[:500], decorators=decorators,
            extraction_method=ExtractionMethod.AST_STATIC, language="python"
        ))
        # 函数属于当前模块/类
        self.edges.append(self.extractor._make_edge(fn_id, self._current_scope, "member_of"))

        self._scope_stack.append(fn_id)
        self.generic_visit(node)
        self._scope_stack.pop()

    visit_AsyncFunctionDef = visit_FunctionDef

    def visit_ClassDef(self, node: ast.ClassDef) -> None:
        cls_id = self.extractor._make_node_id(self.path, node.name, "class")
        decorators = [ast.unparse(d) for d in node.decorator_list]
        docstring = ast.get_docstring(node) or ""

        self.nodes.append(Node(
            id=cls_id, label=node.name, kind="class",
            source_file=str(self.path),
            source_location=f"L{node.lineno}-L{node.end_lineno}",
            docstring=docstring[:500], decorators=decorators,
            extraction_method=ExtractionMethod.AST_STATIC, language="python"
        ))
        # 继承关系
        for base in node.bases:
            base_name = ast.unparse(base)
            base_id = f"external::{base_name}"
            self.edges.append(self.extractor._make_edge(
                cls_id, base_id, "inherits",
                confidence=ConfidenceLevel.INFERRED, score=0.9
            ))
        self.edges.append(self.extractor._make_edge(cls_id, self._current_scope, "member_of"))

        self._scope_stack.append(cls_id)
        self.generic_visit(node)
        self._scope_stack.pop()

    def visit_Call(self, node: ast.Call) -> None:
        """检测函数调用（INFERRED，因为需要运行时才能完全解析）"""
        try:
            callee_name = ast.unparse(node.func)
            # 简单调用（非方法链）
            if "." not in callee_name or callee_name.count(".") == 1:
                callee_id = f"inferred_call::{callee_name}"
                self.edges.append(self.extractor._make_edge(
                    self._current_scope, callee_id, "calls",
                    confidence=ConfidenceLevel.INFERRED, score=0.8
                ))
        except Exception:
            pass
        self.generic_visit(node)


# ─────────────────────────── TypeScript/JavaScript 提取器（正则 fallback）───────────────────────────

class TypeScriptExtractor(BaseExtractor):
    """
    TypeScript/JavaScript 提取器

    GitNexus 创新：语言感知的路径别名解析
    """

    language = "typescript"

    # 路径别名解析（GitNexus 核心创新）
    def _resolve_ts_alias(self, import_path: str, tsconfig_paths: dict) -> str:
        """解析 TypeScript 路径别名 @/ → src/"""
        for alias, targets in tsconfig_paths.items():
            alias_prefix = alias.rstrip("*")
            if import_path.startswith(alias_prefix):
                target_prefix = targets[0].rstrip("*")
                return import_path.replace(alias_prefix, target_prefix, 1)
        return import_path

    def _load_tsconfig_paths(self, repo_root: Path) -> dict:
        """加载 tsconfig.json 的路径别名配置"""
        for tsconfig_name in ["tsconfig.json", "tsconfig.base.json"]:
            tsconfig = repo_root / tsconfig_name
            if tsconfig.exists():
                try:
                    data = json.loads(tsconfig.read_text())
                    return data.get("compilerOptions", {}).get("paths", {})
                except Exception:
                    pass
        return {}

    def extract(self, path: Path) -> ExtractionResult:
        try:
            source = path.read_text(encoding="utf-8", errors="replace")
        except IOError:
            return ExtractionResult([], [], str(path), ExtractionMethod.AST_STATIC,
                                    self.language, error="Cannot read file")

        nodes: list[Node] = []
        edges: list[Edge] = []
        module_id = self._make_node_id(path, path.stem, "module")

        nodes.append(Node(
            id=module_id, label=path.stem, kind="module",
            source_file=str(path), source_location="L1",
            extraction_method=ExtractionMethod.AST_STATIC, language=self.language
        ))

        # 提取 import 语句
        import_patterns = [
            r'import\s+.*?from\s+[\'"]([^\'"]+)[\'"]',
            r'require\s*\(\s*[\'"]([^\'"]+)[\'"]\s*\)',
            r'import\s+[\'"]([^\'"]+)[\'"]',
        ]
        for pattern in import_patterns:
            for match in re.finditer(pattern, source, re.MULTILINE):
                imp_path = match.group(1)
                edges.append(self._make_edge(module_id, f"module::{imp_path}", "imports"))

        # 提取函数/类定义（装饰器支持，来自 GitNexus）
        fn_pattern = r'(?:((?:@\w+(?:\(.*?\))?\s*\n)+))?\s*(?:export\s+)?(?:async\s+)?function\s+(\w+)'
        for match in re.finditer(fn_pattern, source, re.MULTILINE):
            decorators_raw, fn_name = match.group(1) or "", match.group(2)
            decorators = re.findall(r'@(\w+)', decorators_raw)
            fn_id = self._make_node_id(path, fn_name, "function")
            lineno = source[:match.start()].count("\n") + 1
            nodes.append(Node(
                id=fn_id, label=fn_name, kind="function",
                source_file=str(path), source_location=f"L{lineno}",
                decorators=decorators,
                extraction_method=ExtractionMethod.AST_STATIC, language=self.language
            ))
            edges.append(self._make_edge(fn_id, module_id, "member_of"))

        # 提取类定义
        cls_pattern = r'(?:export\s+)?class\s+(\w+)(?:\s+extends\s+(\w+))?'
        for match in re.finditer(cls_pattern, source, re.MULTILINE):
            cls_name, base_name = match.group(1), match.group(2)
            cls_id = self._make_node_id(path, cls_name, "class")
            lineno = source[:match.start()].count("\n") + 1
            nodes.append(Node(
                id=cls_id, label=cls_name, kind="class",
                source_file=str(path), source_location=f"L{lineno}",
                extraction_method=ExtractionMethod.AST_STATIC, language=self.language
            ))
            edges.append(self._make_edge(cls_id, module_id, "member_of"))
            if base_name:
                edges.append(self._make_edge(
                    cls_id, f"class::{base_name}", "inherits",
                    confidence=ConfidenceLevel.INFERRED, score=0.9
                ))

        return ExtractionResult(nodes, edges, str(path), ExtractionMethod.AST_STATIC, self.language)


# ─────────────────────────── 提取器路由 ───────────────────────────

class ASTExtractorRouter:
    """
    多语言提取器路由

    根据文件语言选择对应的提取器
    """

    _extractors: dict[str, type[BaseExtractor]] = {
        "python": PythonExtractor,
        "typescript": TypeScriptExtractor,
        "javascript": TypeScriptExtractor,  # JS 共用 TS 提取器
        "jsx": TypeScriptExtractor,
        "tsx": TypeScriptExtractor,
    }

    @classmethod
    def get_extractor(cls, language: str) -> BaseExtractor | None:
        extractor_cls = cls._extractors.get(language)
        if extractor_cls:
            return extractor_cls()
        return None

    @classmethod
    def register(cls, language: str, extractor_cls: type[BaseExtractor]) -> None:
        """注册新的语言提取器（插件系统用）"""
        cls._extractors[language] = extractor_cls

    @classmethod
    def extract(cls, path: Path, language: str) -> ExtractionResult:
        extractor = cls.get_extractor(language)
        if extractor is None:
            return ExtractionResult(
                [], [], str(path), ExtractionMethod.AST_STATIC, language,
                error=f"No extractor for language: {language}"
            )
        return extractor.extract(path)

"""
CGN 图存储层（Storage Layer）

双存储策略：
- NetworkX：内存图计算（Graphify 风格，支持 Leiden 聚类）
- SQLite：持久化元数据 + 图快照（code-review-graph 风格）

注意：完整实现中将用 KuzuDB 替代 SQLite 作为主图存储（GitNexus 风格）
本模块提供无重依赖的参考实现
"""

from __future__ import annotations
import json
import sqlite3
import time
from pathlib import Path
from typing import Any, Iterator

try:
    import networkx as nx
    HAS_NETWORKX = True
except ImportError:
    HAS_NETWORKX = False

from .models import Community, Edge, Node, Process, ConfidenceLevel


# ─────────────────────────── NetworkX 图包装器 ───────────────────────────

class CGNGraph:
    """
    CGN 核心图结构

    基于 NetworkX 的内存图（Graphify 风格）
    支持：Leiden 聚类、God Node 分析、BFS/DFS 查询
    """

    def __init__(self):
        if not HAS_NETWORKX:
            raise RuntimeError("networkx is required. Install with: pip install networkx")
        self.G: nx.DiGraph = nx.DiGraph()
        self._nodes: dict[str, Node] = {}
        self._edges: list[Edge] = []

    def add_node(self, node: Node) -> None:
        self._nodes[node.id] = node
        self.G.add_node(node.id, **{
            "label": node.label,
            "kind": node.kind,
            "source_file": node.source_file,
            "community_id": node.community_id,
            "pagerank": node.pagerank,
            "is_god_node": node.is_god_node,
        })

    def add_edge(self, edge: Edge) -> None:
        self._edges.append(edge)
        self.G.add_edge(edge.source, edge.target, **{
            "relation": edge.relation,
            "confidence": edge.confidence.value,
            "confidence_score": edge.confidence_score,
        })

    def add_nodes(self, nodes: list[Node]) -> None:
        for n in nodes:
            self.add_node(n)

    def add_edges(self, edges: list[Edge]) -> None:
        for e in edges:
            self.add_edge(e)

    def get_node(self, node_id: str) -> Node | None:
        return self._nodes.get(node_id)

    def get_neighbors(self, node_id: str, relation: str | None = None) -> list[Node]:
        """获取节点的邻居（出边）"""
        result = []
        for _, dst, data in self.G.out_edges(node_id, data=True):
            if relation is None or data.get("relation") == relation:
                node = self._nodes.get(dst)
                if node:
                    result.append(node)
        return result

    def get_callers(self, node_id: str) -> list[Node]:
        """获取调用当前节点的节点（入边）"""
        result = []
        for src, _, data in self.G.in_edges(node_id, data=True):
            if data.get("relation") == "calls":
                node = self._nodes.get(src)
                if node:
                    result.append(node)
        return result

    def bfs(self, start_id: str, max_hops: int = 3, 
            relation_filter: str | None = None) -> list[Node]:
        """BFS 图遍历（Graphify query 风格）"""
        from collections import deque
        visited = set()
        queue = deque([(start_id, 0)])
        result = []

        while queue:
            node_id, depth = queue.popleft()
            if node_id in visited or depth > max_hops:
                continue
            visited.add(node_id)
            node = self._nodes.get(node_id)
            if node:
                result.append(node)
            for _, dst, data in self.G.out_edges(node_id, data=True):
                if relation_filter is None or data.get("relation") == relation_filter:
                    if dst not in visited:
                        queue.append((dst, depth + 1))

        return result

    def dfs(self, start_id: str, max_hops: int = 5,
            relation_filter: str | None = None) -> list[Node]:
        """DFS 路径追踪（Graphify --dfs 风格）"""
        visited = set()
        result = []

        def _dfs(node_id: str, depth: int) -> None:
            if node_id in visited or depth > max_hops:
                return
            visited.add(node_id)
            node = self._nodes.get(node_id)
            if node:
                result.append(node)
            for _, dst, data in self.G.out_edges(node_id, data=True):
                if relation_filter is None or data.get("relation") == relation_filter:
                    _dfs(dst, depth + 1)

        _dfs(start_id, 0)
        return result

    def compute_pagerank(self) -> dict[str, float]:
        """计算 PageRank（用于 God Node 检测）"""
        pr = nx.pagerank(self.G, alpha=0.85)
        for node_id, score in pr.items():
            if node_id in self._nodes:
                self._nodes[node_id].pagerank = score
            self.G.nodes[node_id]["pagerank"] = score
        return pr

    def find_god_nodes(self, top_n: int = 10) -> list[Node]:
        """
        检测上帝节点（Graphify 核心分析）
        综合度中心性 + PageRank
        """
        degree_centrality = nx.degree_centrality(self.G)
        pr = self.compute_pagerank()

        # 综合评分
        scores = {
            nid: 0.6 * pr.get(nid, 0) + 0.4 * degree_centrality.get(nid, 0)
            for nid in self._nodes
        }
        top_ids = sorted(scores, key=scores.get, reverse=True)[:top_n]

        result = []
        for nid in top_ids:
            node = self._nodes.get(nid)
            if node:
                node.is_god_node = True
                self.G.nodes[nid]["is_god_node"] = True
                result.append(node)
        return result

    def find_surprise_connections(self) -> list[Edge]:
        """
        检测惊喜连接：跨社区的高置信度边（Graphify 分析）
        揭示隐藏的架构耦合
        """
        surprises = []
        for edge in self._edges:
            src_node = self._nodes.get(edge.source)
            dst_node = self._nodes.get(edge.target)
            if (src_node and dst_node
                    and src_node.community_id is not None
                    and dst_node.community_id is not None
                    and src_node.community_id != dst_node.community_id
                    and edge.confidence == ConfidenceLevel.EXTRACTED):
                surprises.append(edge)
        return surprises

    @property
    def node_count(self) -> int:
        return len(self._nodes)

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def to_dict(self) -> dict:
        """序列化为字典（用于持久化）"""
        return {
            "nodes": [
                {
                    "id": n.id, "label": n.label, "kind": n.kind,
                    "source_file": n.source_file, "source_location": n.source_location,
                    "community_id": n.community_id, "pagerank": n.pagerank,
                    "is_god_node": n.is_god_node,
                }
                for n in self._nodes.values()
            ],
            "edges": [
                {
                    "source": e.source, "target": e.target, "relation": e.relation,
                    "confidence": e.confidence.value, "confidence_score": e.confidence_score,
                }
                for e in self._edges
            ],
        }


# ─────────────────────────── SQLite 持久化层（code-review-graph 风格）───────────────────────────

class GraphStorage:
    """
    图谱 SQLite 持久化层

    来源：code-review-graph 的 SQLite 设计
    功能：跨会话持久、快速增量更新、元数据管理
    """

    def __init__(self, db_path: Path):
        self.db_path = db_path
        db_path.parent.mkdir(parents=True, exist_ok=True)
        self._init_schema()

    def _init_schema(self) -> None:
        with sqlite3.connect(self.db_path) as conn:
            conn.executescript("""
                CREATE TABLE IF NOT EXISTS nodes (
                    id TEXT PRIMARY KEY,
                    label TEXT NOT NULL,
                    kind TEXT,
                    source_file TEXT,
                    source_location TEXT,
                    signature TEXT,
                    docstring TEXT,
                    decorators TEXT,
                    community_id INTEGER,
                    pagerank REAL DEFAULT 0,
                    is_god_node INTEGER DEFAULT 0,
                    extraction_method TEXT,
                    language TEXT
                );

                CREATE TABLE IF NOT EXISTS edges (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source TEXT NOT NULL,
                    target TEXT NOT NULL,
                    relation TEXT NOT NULL,
                    confidence TEXT DEFAULT 'EXTRACTED',
                    confidence_score REAL DEFAULT 1.0,
                    extraction_method TEXT,
                    FOREIGN KEY (source) REFERENCES nodes(id),
                    FOREIGN KEY (target) REFERENCES nodes(id)
                );

                CREATE TABLE IF NOT EXISTS communities (
                    id INTEGER PRIMARY KEY,
                    name TEXT,
                    heuristic_label TEXT,
                    cohesion_score REAL,
                    member_count INTEGER,
                    description TEXT
                );

                CREATE TABLE IF NOT EXISTS processes (
                    id TEXT PRIMARY KEY,
                    name TEXT,
                    entry_point TEXT,
                    entry_file TEXT,
                    risk_score REAL DEFAULT 0
                );

                CREATE TABLE IF NOT EXISTS process_steps (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    process_id TEXT,
                    node_id TEXT,
                    step_order INTEGER,
                    step_type TEXT,
                    FOREIGN KEY (process_id) REFERENCES processes(id)
                );

                CREATE TABLE IF NOT EXISTS graph_meta (
                    key TEXT PRIMARY KEY,
                    value TEXT
                );

                CREATE INDEX IF NOT EXISTS idx_edges_source ON edges(source);
                CREATE INDEX IF NOT EXISTS idx_edges_target ON edges(target);
                CREATE INDEX IF NOT EXISTS idx_nodes_file ON nodes(source_file);
                CREATE INDEX IF NOT EXISTS idx_nodes_community ON nodes(community_id);
            """)

    def save_graph(self, graph: CGNGraph) -> None:
        """保存图谱到 SQLite"""
        with sqlite3.connect(self.db_path) as conn:
            # 保存节点
            conn.executemany(
                """INSERT OR REPLACE INTO nodes 
                   (id, label, kind, source_file, source_location, 
                    decorators, community_id, pagerank, is_god_node, 
                    extraction_method, language)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                [
                    (n.id, n.label, n.kind, n.source_file, n.source_location,
                     json.dumps(n.decorators), n.community_id, n.pagerank,
                     1 if n.is_god_node else 0,
                     n.extraction_method.value if n.extraction_method else None,
                     n.language)
                    for n in graph._nodes.values()
                ]
            )
            # 保存边
            conn.execute("DELETE FROM edges")
            conn.executemany(
                """INSERT INTO edges (source, target, relation, confidence, confidence_score)
                   VALUES (?, ?, ?, ?, ?)""",
                [
                    (e.source, e.target, e.relation, e.confidence.value, e.confidence_score)
                    for e in graph._edges
                ]
            )
            # 更新元数据
            conn.execute(
                "INSERT OR REPLACE INTO graph_meta VALUES (?, ?)",
                ("last_saved", str(time.time()))
            )
            conn.execute(
                "INSERT OR REPLACE INTO graph_meta VALUES (?, ?)",
                ("node_count", str(graph.node_count))
            )
            conn.commit()

    def load_graph(self) -> CGNGraph:
        """从 SQLite 加载图谱"""
        graph = CGNGraph()
        with sqlite3.connect(self.db_path) as conn:
            for row in conn.execute("SELECT * FROM nodes"):
                node = Node(
                    id=row[0], label=row[1], kind=row[2] or "unknown",
                    source_file=row[3] or "", source_location=row[4] or "",
                    decorators=json.loads(row[7]) if row[7] else [],
                    community_id=row[8], pagerank=row[9] or 0.0,
                    is_god_node=bool(row[10]),
                )
                graph.add_node(node)

            for row in conn.execute("SELECT * FROM edges"):
                edge = Edge(
                    source=row[1], target=row[2], relation=row[3],
                    confidence=ConfidenceLevel(row[4]) if row[4] else ConfidenceLevel.EXTRACTED,
                    confidence_score=row[5] or 1.0,
                )
                graph.add_edge(edge)

        return graph

    def delete_nodes_by_file(self, file_path: str) -> None:
        """删除指定文件的所有节点（增量更新时使用）"""
        with sqlite3.connect(self.db_path) as conn:
            node_ids = [
                row[0] for row in
                conn.execute("SELECT id FROM nodes WHERE source_file = ?", (file_path,))
            ]
            for nid in node_ids:
                conn.execute("DELETE FROM edges WHERE source = ? OR target = ?", (nid, nid))
            conn.execute("DELETE FROM nodes WHERE source_file = ?", (file_path,))
            conn.commit()

    def search_nodes(self, query: str, kind: str | None = None, limit: int = 20) -> list[dict]:
        """关键词搜索节点（BM25 近似：LIKE 匹配）"""
        with sqlite3.connect(self.db_path) as conn:
            if kind:
                rows = conn.execute(
                    "SELECT * FROM nodes WHERE (label LIKE ? OR source_file LIKE ?) AND kind = ? LIMIT ?",
                    (f"%{query}%", f"%{query}%", kind, limit)
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT * FROM nodes WHERE label LIKE ? OR source_file LIKE ? LIMIT ?",
                    (f"%{query}%", f"%{query}%", limit)
                ).fetchall()

        return [
            {"id": r[0], "label": r[1], "kind": r[2], "source_file": r[3]}
            for r in rows
        ]

    def get_impact(self, node_id: str, max_depth: int = 5) -> list[dict]:
        """
        保守召回影响分析（code-review-graph 核心能力）
        反向 BFS：谁依赖 node_id？
        """
        visited = set()
        result = []
        queue = [(node_id, 0)]

        with sqlite3.connect(self.db_path) as conn:
            while queue:
                current_id, depth = queue.pop(0)
                if current_id in visited or depth > max_depth:
                    continue
                visited.add(current_id)

                # 查找谁调用/依赖当前节点
                callers = conn.execute(
                    "SELECT source FROM edges WHERE target = ? AND relation IN ('calls', 'imports', 'uses')",
                    (current_id,)
                ).fetchall()

                for (caller_id,) in callers:
                    if caller_id not in visited:
                        risk = "high" if depth == 0 else ("medium" if depth <= 2 else "low")
                        result.append({
                            "node_id": caller_id,
                            "depth": depth + 1,
                            "risk_level": risk,
                            "confidence": 1.0,  # 保守召回：永远报告
                        })
                        queue.append((caller_id, depth + 1))

        return result

    def get_stats(self) -> dict:
        """获取图谱统计信息"""
        with sqlite3.connect(self.db_path) as conn:
            node_count = conn.execute("SELECT COUNT(*) FROM nodes").fetchone()[0]
            edge_count = conn.execute("SELECT COUNT(*) FROM edges").fetchone()[0]
            community_count = conn.execute("SELECT COUNT(*) FROM communities").fetchone()[0]
            process_count = conn.execute("SELECT COUNT(*) FROM processes").fetchone()[0]
            last_saved = conn.execute(
                "SELECT value FROM graph_meta WHERE key = 'last_saved'"
            ).fetchone()

        return {
            "node_count": node_count,
            "edge_count": edge_count,
            "community_count": community_count,
            "process_count": process_count,
            "last_saved": last_saved[0] if last_saved else None,
        }

"""
CGN 插件框架（Plugin Framework）

设计灵感：
- GitNexus: MCP 工具注册机制
- OpenCode: .opencode/plugins/ 插件文件系统
- Graphify: Skill 文件机制

插件可以：
1. Hook 到提取流水线的各个生命周期点
2. 注册自定义 MCP 工具和资源
3. 扩展语言支持（注册新提取器）
4. 自定义导出格式
"""

from __future__ import annotations
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Callable

from ..core.models import (
    Community, ExtractionResult, Node, Edge, Process, QueryResult
)


# ─────────────────────────── MCP 工具定义 ───────────────────────────

@dataclass
class MCPTool:
    """MCP 工具描述（GitNexus 风格）"""
    name: str
    description: str
    input_schema: dict
    handler: Callable[..., Any]


@dataclass
class MCPResource:
    """MCP 资源描述"""
    uri_template: str          # e.g. "cgn://repo/{name}/clusters"
    description: str
    handler: Callable[..., Any]


# ─────────────────────────── 插件基类 ───────────────────────────

class CGNPlugin(ABC):
    """
    所有 CGN 插件的基类

    插件实现任意子集的 hook 方法即可，无需实现全部接口
    """

    name: str = ""
    version: str = "0.1.0"
    description: str = ""

    # ── 提取层 Hooks ──

    def on_before_extract(self, path: Path, language: str) -> None:
        """文件提取前回调"""
        pass

    def on_after_extract(self, result: ExtractionResult) -> ExtractionResult:
        """文件提取后回调，可修改结果"""
        return result

    def on_before_merge(self, results: list[ExtractionResult]) -> list[ExtractionResult]:
        """合并所有提取结果前回调"""
        return results

    # ── 聚类层 Hooks ──

    def on_before_cluster(self, nodes: list[Node], edges: list[Edge]) -> tuple[list[Node], list[Edge]]:
        """聚类前回调"""
        return nodes, edges

    def on_after_cluster(self, communities: list[Community]) -> list[Community]:
        """聚类后回调，可修改社区列表"""
        return communities

    # ── 分析层 Hooks ──

    def on_after_process_trace(self, processes: list[Process]) -> list[Process]:
        """Process 追踪后回调"""
        return processes

    # ── 查询层 Hooks ──

    def on_before_query(self, query_str: str, query_type: str) -> str:
        """查询前回调，可修改查询"""
        return query_str

    def on_after_query(self, result: QueryResult) -> QueryResult:
        """查询后回调，可修改结果"""
        return result

    # ── 扩展注册 ──

    def register_tools(self) -> list[MCPTool]:
        """注册自定义 MCP 工具"""
        return []

    def register_resources(self) -> list[MCPResource]:
        """注册自定义 MCP 资源"""
        return []

    def register_extractors(self) -> dict[str, Any]:
        """
        注册自定义语言提取器
        返回 {language_name: ExtractorClass} 字典
        """
        return {}


# ─────────────────────────── 插件注册中心 ───────────────────────────

class PluginRegistry:
    """插件注册和生命周期管理"""

    def __init__(self):
        self._plugins: list[CGNPlugin] = []
        self._tools: dict[str, MCPTool] = {}
        self._resources: list[MCPResource] = []

    def register(self, plugin: CGNPlugin) -> None:
        """注册插件"""
        self._plugins.append(plugin)

        # 注册工具
        for tool in plugin.register_tools():
            self._tools[tool.name] = tool

        # 注册资源
        self._resources.extend(plugin.register_resources())

        # 注册提取器
        from ..core.extract import ASTExtractorRouter
        for lang, extractor_cls in plugin.register_extractors().items():
            ASTExtractorRouter.register(lang, extractor_cls)

        print(f"[CGN] Plugin registered: {plugin.name} v{plugin.version}")

    def get_tool(self, name: str) -> MCPTool | None:
        return self._tools.get(name)

    def list_tools(self) -> list[MCPTool]:
        return list(self._tools.values())

    # ── Hook 调度 ──

    def fire_before_extract(self, path: Path, language: str) -> None:
        for plugin in self._plugins:
            plugin.on_before_extract(path, language)

    def fire_after_extract(self, result: ExtractionResult) -> ExtractionResult:
        for plugin in self._plugins:
            result = plugin.on_after_extract(result)
        return result

    def fire_after_cluster(self, communities: list[Community]) -> list[Community]:
        for plugin in self._plugins:
            communities = plugin.on_after_cluster(communities)
        return communities

    def fire_after_query(self, result: QueryResult) -> QueryResult:
        for plugin in self._plugins:
            result = plugin.on_after_query(result)
        return result


# ─────────────────────────── 内置插件示例 ───────────────────────────

class SecurityAnalyzerPlugin(CGNPlugin):
    """
    安全分析插件
    检测高风险模式：SQL注入、命令注入、硬编码密钥等
    """

    name = "security_analyzer"
    version = "0.1.0"
    description = "Detect security anti-patterns in extracted code"

    RISK_PATTERNS = {
        "sql_injection": ["execute(", "raw(", "format_sql"],
        "cmd_injection": ["os.system(", "subprocess.call(", "exec("],
        "hardcoded_secret": ["password =", "api_key =", "secret =", "token ="],
    }

    def on_after_extract(self, result: ExtractionResult) -> ExtractionResult:
        """在节点上标注安全风险"""
        for node in result.nodes:
            risks = []
            label_lower = node.label.lower()
            sig_lower = (node.signature or "").lower()
            combined = label_lower + " " + sig_lower

            for risk_type, patterns in self.RISK_PATTERNS.items():
                if any(p in combined for p in patterns):
                    risks.append(risk_type)

            if risks and node.docstring is not None:
                node.docstring = f"[SECURITY_RISK: {', '.join(risks)}] " + node.docstring

        return result

    def register_tools(self) -> list[MCPTool]:
        return [
            MCPTool(
                name="security_scan",
                description="Scan knowledge graph for security anti-patterns",
                input_schema={"type": "object", "properties": {
                    "risk_types": {"type": "array", "items": {"type": "string"}}
                }},
                handler=self._scan_handler,
            )
        ]

    def _scan_handler(self, risk_types: list[str] | None = None) -> dict:
        return {"message": "Security scan complete", "risks": []}


class DeadCodeDetectorPlugin(CGNPlugin):
    """
    死代码检测插件
