"""
CGN MCP 服务器（MCP Server）

融合 GitNexus 的 7工具+6资源URI 设计，扩展为 10工具+8资源
标准 MCP stdio 协议实现

工具列表：
1. search        - 混合搜索（BM25 + Process分组）
2. context       - 360° 上下文查询
3. impact        - 变更影响分析（保守召回）
4. process       - 执行流追踪
5. detect_changes - Git Diff 影响分析
6. god_nodes     - 上帝节点分析
7. rename        - 图感知重命名（建议）
8. generate_wiki - Wiki 生成
9. repos         - 多仓库管理
10. query        - 原始图查询（SQL/Cypher）
"""

from __future__ import annotations
import json
import sys
from pathlib import Path
from typing import Any

from ..core.pipeline import CGNPipeline
from ..core.detect import RepoRegistry
from ..plugins.base import PluginRegistry


class CGNMCPServer:
    """
    CGN MCP 服务器（stdio 协议）

    与 AI 编码助手（Claude Code、Cursor、OpenCode 等）集成
    """

    def __init__(
        self,
        registry: RepoRegistry,
        plugin_registry: PluginRegistry | None = None,
    ):
        self.registry = registry
        self.plugin_registry = plugin_registry or PluginRegistry()
        self._pipelines: dict[str, CGNPipeline] = {}  # 懒加载连接池（GitNexus 风格）

        # 内置工具定义
        self.tools = self._define_tools()

    # ─────────────────────────── MCP stdio 协议 ───────────────────────────

    def run_stdio(self) -> None:
        """运行 MCP stdio 服务器（标准协议）"""
        print("[CGN] MCP Server starting (stdio mode)...", file=sys.stderr)

        for line in sys.stdin:
            line = line.strip()
            if not line:
                continue
            try:
                request = json.loads(line)
                response = self._handle_request(request)
                print(json.dumps(response), flush=True)
            except json.JSONDecodeError:
                error_resp = {"error": "Invalid JSON", "code": -32700}
                print(json.dumps(error_resp), flush=True)
            except Exception as e:
                error_resp = {"error": str(e), "code": -32603}
                print(json.dumps(error_resp), flush=True)

    def _handle_request(self, request: dict) -> dict:
        """处理 MCP 请求"""
        method = request.get("method", "")
        params = request.get("params", {})
        request_id = request.get("id")

        if method == "initialize":
            return self._respond(request_id, self._handle_initialize())
        elif method == "tools/list":
            return self._respond(request_id, {"tools": self.tools})
        elif method == "tools/call":
            result = self._handle_tool_call(params.get("name"), params.get("arguments", {}))
            return self._respond(request_id, result)
        elif method == "resources/list":
            return self._respond(request_id, {"resources": self._list_resources()})
        elif method == "resources/read":
            result = self._handle_resource_read(params.get("uri", ""))
            return self._respond(request_id, result)
        else:
            return self._error(request_id, f"Unknown method: {method}", -32601)

    def _respond(self, request_id: Any, result: Any) -> dict:
        return {"jsonrpc": "2.0", "id": request_id, "result": result}

    def _error(self, request_id: Any, message: str, code: int) -> dict:
        return {"jsonrpc": "2.0", "id": request_id,
                "error": {"code": code, "message": message}}

    # ─────────────────────────── MCP 初始化 ───────────────────────────

    def _handle_initialize(self) -> dict:
        return {
            "protocolVersion": "2024-11-05",
            "capabilities": {
                "tools": {"listChanged": False},
                "resources": {"subscribe": False, "listChanged": False},
            },
            "serverInfo": {
                "name": "cgn",
                "version": "0.1.0",
                "description": "CodeGraph-Nexus: Unified Code Knowledge Graph (Graphify × code-review-graph × GitNexus)",
            }
        }

    # ─────────────────────────── 工具处理 ───────────────────────────

    def _handle_tool_call(self, name: str, args: dict) -> dict:
        """分发工具调用"""
        handlers = {
            "search": self._tool_search,
            "context": self._tool_context,
            "impact": self._tool_impact,
            "process": self._tool_process,
            "detect_changes": self._tool_detect_changes,
            "god_nodes": self._tool_god_nodes,
            "rename": self._tool_rename,
            "generate_wiki": self._tool_generate_wiki,
            "repos": self._tool_repos,
            "query": self._tool_query,
        }

        # 插件工具
        plugin_tool = self.plugin_registry.get_tool(name)
        if plugin_tool:
            result = plugin_tool.handler(**args)
            return {"content": [{"type": "text", "text": json.dumps(result, ensure_ascii=False)}]}

        handler = handlers.get(name)
        if not handler:
            return {"content": [{"type": "text", "text": f"Unknown tool: {name}"}],
                    "isError": True}

        try:
            result = handler(args)
            return {"content": [{"type": "text", "text": json.dumps(result, ensure_ascii=False, indent=2)}]}
        except Exception as e:
            return {"content": [{"type": "text", "text": f"Error: {e}"}], "isError": True}

    def _tool_search(self, args: dict) -> dict:
        """
        混合搜索（BM25 + Process分组）
        GitNexus search tool
        """
        query = args.get("query", "")
        repo_name = args.get("repo", self._default_repo())
        kind = args.get("kind")
        limit = args.get("limit", 20)

        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        # 关键词搜索
        results = pipeline.storage.search_nodes(query, kind=kind, limit=limit)

        return {
            "query": query,
            "results": results,
            "count": len(results),
            "method": "keyword_bm25",
        }

    def _tool_context(self, args: dict) -> dict:
        """360° 上下文查询（GitNexus context tool）"""
        symbol = args.get("symbol", "")
        repo_name = args.get("repo", self._default_repo())
        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        graph = pipeline.storage.load_graph()
        node = next((n for n in graph._nodes.values() if n.label == symbol), None)
        if not node:
            return {"error": f"Symbol not found: {symbol}"}

        callers = graph.get_callers(node.id)
        callees = graph.get_neighbors(node.id, relation="calls")
        imports = graph.get_neighbors(node.id, relation="imports")

        return {
            "symbol": symbol,
            "kind": node.kind,
            "location": f"{node.source_file}:{node.source_location}",
            "community_id": node.community_id,
            "is_god_node": node.is_god_node,
            "pagerank": node.pagerank,
            "callers": [{"label": n.label, "file": n.source_file} for n in callers],
            "callees": [{"label": n.label, "file": n.source_file} for n in callees],
            "imports": [{"label": n.label, "file": n.source_file} for n in imports],
        }

    def _tool_impact(self, args: dict) -> dict:
        """
        变更影响分析（code-review-graph 保守召回风格）
        宁多勿漏，100% 召回率保证
        """
        symbol = args.get("symbol", "")
        repo_name = args.get("repo", self._default_repo())
        max_depth = args.get("max_depth", 5)

        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        impacts = pipeline.query_impact(symbol, max_depth=max_depth)

        high = [i for i in impacts if i["risk_level"] == "high"]
        medium = [i for i in impacts if i["risk_level"] == "medium"]
        low = [i for i in impacts if i["risk_level"] == "low"]

        return {
            "symbol": symbol,
            "recall_guarantee": True,  # 永远为 True（保守策略）
            "total_impacted": len(impacts),
            "risk_summary": {"high": len(high), "medium": len(medium), "low": len(low)},
            "high_risk": high,
            "medium_risk": medium,
            "low_risk": low,
        }

    def _tool_process(self, args: dict) -> dict:
        """执行流追踪（GitNexus process tool）"""
        repo_name = args.get("repo", self._default_repo())
        process_id = args.get("process_id")

        import sqlite3
        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        with sqlite3.connect(pipeline.storage.db_path) as conn:
            if process_id:
                proc = conn.execute(
                    "SELECT * FROM processes WHERE id = ?", (process_id,)
                ).fetchone()
                if not proc:
                    return {"error": f"Process not found: {process_id}"}
                steps = conn.execute(
                    "SELECT * FROM process_steps WHERE process_id = ? ORDER BY step_order",
                    (process_id,)
                ).fetchall()
                return {
                    "id": proc[0], "name": proc[1],
                    "entry_point": proc[2], "entry_file": proc[3],
                    "steps": [{"node_id": s[2], "step_order": s[3], "type": s[4]} for s in steps],
                }
            else:
                procs = conn.execute("SELECT id, name, entry_point, entry_file FROM processes").fetchall()
                return {"processes": [{"id": p[0], "name": p[1], "entry": p[2]} for p in procs]}

    def _tool_detect_changes(self, args: dict) -> dict:
        """Git Diff 影响分析"""
        diff = args.get("diff", "")
        repo_name = args.get("repo", self._default_repo())

        # 从 diff 中提取变更的符号名
        changed_symbols = []
        for line in diff.split("\n"):
            if line.startswith("-") or line.startswith("+"):
                # 简单提取函数名
                import re
                matches = re.findall(r'def (\w+)|function (\w+)|class (\w+)', line)
                for m in matches:
                    sym = next(s for s in m if s)
                    if sym:
                        changed_symbols.append(sym)

        all_impacts = []
        for sym in changed_symbols:
            impacts = self._tool_impact({"symbol": sym, "repo": repo_name})
            if "total_impacted" in impacts:
                all_impacts.append({"symbol": sym, **impacts})

        return {
            "changed_symbols": changed_symbols,
            "impact_analysis": all_impacts,
            "risk_summary": "See individual symbol impacts above",
        }

    def _tool_god_nodes(self, args: dict) -> dict:
        """上帝节点分析（Graphify 风格）"""
        repo_name = args.get("repo", self._default_repo())
        top_n = args.get("top_n", 10)
        include_surprises = args.get("include_surprises", True)

        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        graph = pipeline.storage.load_graph()
        god_nodes = graph.find_god_nodes(top_n=top_n)
        result = {
            "god_nodes": [
                {"id": n.id, "label": n.label, "kind": n.kind,
                 "file": n.source_file, "pagerank": n.pagerank}
                for n in god_nodes
            ]
        }

        if include_surprises:
            surprises = graph.find_surprise_connections()
            result["surprise_connections"] = [
                {"source": e.source, "target": e.target, "relation": e.relation}
                for e in surprises[:10]
            ]

        return result

    def _tool_rename(self, args: dict) -> dict:
        """图感知重命名建议（GitNexus rename tool）"""
        old_name = args.get("old_name", "")
        new_name = args.get("new_name", "")
        dry_run = args.get("dry_run", True)

        return {
            "old_name": old_name,
            "new_name": new_name,
            "dry_run": dry_run,
            "affected_files": [],  # 需要图查询填充
            "confidence": "INFERRED",
            "warning": "Review graph impact before applying rename",
        }

    def _tool_generate_wiki(self, args: dict) -> dict:
        """Wiki 生成（GitNexus wiki 功能）"""
        return {"message": "Wiki generation requires LLM API configuration", "status": "pending"}

    def _tool_repos(self, args: dict) -> dict:
        """多仓库管理（GitNexus repos tool）"""
        action = args.get("action", "list")
        if action == "list":
            return {"repos": self.registry.list_repos()}
        elif action == "register":
            path = args.get("path")
            name = args.get("name")
            if path:
                repo_id = self.registry.register(Path(path), name)
                return {"registered": True, "id": repo_id}
        elif action == "unregister":
            repo_id = args.get("id")
            if repo_id:
                ok = self.registry.unregister(repo_id)
                return {"unregistered": ok}
        return {"error": "Invalid action"}

    def _tool_query(self, args: dict) -> dict:
        """原始图查询（SQL fallback，Cypher 需要 KuzuDB）"""
        query = args.get("query", "")
        repo_name = args.get("repo", self._default_repo())

        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        # SQL 查询 SQLite（fallback）
        import sqlite3
        try:
            with sqlite3.connect(pipeline.storage.db_path) as conn:
                rows = conn.execute(query).fetchall()
            return {"results": [list(r) for r in rows], "count": len(rows)}
        except Exception as e:
            return {"error": str(e)}

    # ─────────────────────────── 资源处理 ───────────────────────────

    def _list_resources(self) -> list[dict]:
        repos = self.registry.list_repos()
        resources = []
        for repo in repos:
            name = repo["name"]
            for endpoint in ["context", "clusters", "processes", "god_nodes", "schema", "report"]:
                resources.append({
                    "uri": f"cgn://repo/{name}/{endpoint}",
                    "name": f"{name}/{endpoint}",
                    "description": f"CGN {endpoint} for {name}",
                    "mimeType": "application/json",
                })
        return resources

    def _handle_resource_read(self, uri: str) -> dict:
        """处理资源读取请求"""
        parts = uri.replace("cgn://repo/", "").split("/")
        if len(parts) < 2:
            return {"error": "Invalid URI"}

        repo_name = parts[0]
        resource_type = parts[1]
        pipeline = self._get_pipeline(repo_name)
        if not pipeline:
            return {"error": f"Repo not found: {repo_name}"}

        if resource_type == "context":
            return {"contents": [{"type": "text", "text": json.dumps(pipeline.status())}]}
        elif resource_type == "report":
            report_path = pipeline.output_dir / "GRAPH_REPORT.md"
            if report_path.exists():
                return {"contents": [{"type": "text", "text": report_path.read_text()}]}

        return {"contents": [{"type": "text", "text": "{}"}]}

