    # ─────────────────────────── 内部工具 ───────────────────────────

    def _get_pipeline(self, repo_name: str) -> CGNPipeline | None:
        """懒加载 pipeline（GitNexus 懒连接池）"""
        if repo_name in self._pipelines:
            return self._pipelines[repo_name]

        repos = self.registry.list_repos()
        for repo in repos:
            if repo["name"] == repo_name:
                pipeline = CGNPipeline(Path(repo["path"]))
                self._pipelines[repo_name] = pipeline
                return pipeline
        return None

    def _default_repo(self) -> str:
        """返回第一个注册的仓库名"""
        repos = self.registry.list_repos()
        return repos[0]["name"] if repos else ""
